  '',
  'Если хочешь обновить память, напиши: <b>обновить профиль</b>.'
].join('\n');

return [{
  json: {
    chat_id: user.chat_id,
    airtable_record_id: user.airtable_record_id,
    onboarding_needed: onboardingNeeded,
    telegram_text: onboardingNeeded ? onboardingText : menuText,
    last_task_type: 'profile_onboarding',
    last_question: 'Профиль эксперта: Нужна анкета: кто вы, ниша, ЦА, боли/желания, продукты, оффер, стиль, примеры постов, ограничения.',
    last_raw_text: 'Старт онбординга профиля'
  }
}];

