const update = $json || {};
const callback = update.callback_query || null;
const message = update.message || update.edited_message || callback?.message || {};
const from = callback?.from || message.from || {};
const chat = message.chat || {};
const callbackData = String(callback?.data || '').trim();
const visibleText = callback ? '' : String(message.text || message.caption || '').trim();
const rawText = callbackData || visibleText;
const lower = rawText.toLowerCase().replace(/\s+/g, ' ');
const documentCandidate = !callback ? (message.document || {}) : {};
const documentIsAudio = Boolean(
  documentCandidate.file_id &&
  (
    String(documentCandidate.mime_type || '').startsWith('audio/') ||
    /\.(ogg|oga|opus|mp3|m4a|wav|aac|flac|webm)$/i.test(String(documentCandidate.file_name || ''))
  )
);
const documentAudio = documentIsAudio ? documentCandidate : {};
const videoNoteAudio = !callback && message.video_note ? message.video_note : {};
const audio = callback ? {} : (message.voice || message.audio || (documentAudio.file_id ? documentAudio : null) || videoNoteAudio || {});
const audioKind = callback ? '' : (
  message.voice ? 'voice' :
  message.audio ? 'audio' :
  documentAudio.file_id ? 'document_audio' :
  message.video_note ? 'video_note' :
  ''
);

const labels = {
  content_plan: 'Контент-план',
  telegram_post: 'Пост TG',
  reels_script: 'Reels',
  bot_broadcast: 'Рассылка',
  live_announcement: 'Анонс эфира',
  sales_sequence: 'Цепочка'
};

const typedFormats = {
  'контент-план': 'content_plan',
  'контент план': 'content_plan',
  'пост tg': 'telegram_post',
  'tg пост': 'telegram_post',
  'telegram-пост': 'telegram_post',
  'telegram пост': 'telegram_post',
  'пост в tg': 'telegram_post',
  'reels': 'reels_script',
  'reels-сценарий': 'reels_script',
  'reels сценарий': 'reels_script',
  'рилс': 'reels_script',
  'рилса': 'reels_script',
  'рассылка': 'bot_broadcast',
  'рассылка в боте': 'bot_broadcast',
  'анонс': 'live_announcement',
  'анонс эфира': 'live_announcement',
  'цепочка': 'sales_sequence',
  'продающая цепочка': 'sales_sequence',
  'прогрев': 'sales_sequence'
};

const startWords = ['/start', 'start'];
const menuWords = ['/help', 'help', 'помощь', 'меню', '/menu', 'назад', 'назад в меню', 'menu'];
const profileWords = ['профиль', 'обновить профиль', 'заполнить профиль', 'анкета профиля', 'память профиля', 'profile_start'];
const formatMenuWords = ['форматы', 'выбрать формат', 'формат', 'типы контента', 'format_menu'];
const memoryOnWords = ['с памятью', 'память', 'использовать память', 'использовать контекст', 'контекст', 'контекст вкл', 'память вкл', 'memory_on'];
const memoryOffWords = ['с нуля', 'начать с нуля', 'начать с 0', 'без памяти', 'без контекста', 'новый контекст', 'чистый лист', 'memory_off'];
const memoryResetWords = ['сбросить память', 'очистить память', 'стереть память', 'заново заполнить память', 'memory_reset'];

function inferTaskFromText(value) {
  const text = String(value || '').toLowerCase().replace(/\s+/g, ' ');
  if (!text) return 'auto';
  if (/(контент[-\s]?план|контент[-\s]?сетк|план\s+(?:контента|постов|публикац)|сетка\s+контента)/i.test(text)) return 'content_plan';
  if (/(reels?|рилс|рилса|shorts?|сценар(?:ий|ия).{0,70}(?:ролик|reels?|рилс|shorts?)|(?:ролик|reels?|рилс).{0,70}сценар)/i.test(text)) return 'reels_script';
  if (/((?:telegram|телеграм|tg).{0,35}пост|пост.{0,35}(?:telegram|телеграм|tg)|(?:^|\s)пост(?:\s|$))/i.test(text)) return 'telegram_post';
  if (/(рассыл|сообщ\w*.{0,35}(?:бот|дожим|анкеты?|рассыл|письм)|письм[ао]|дожим|дожать|напомин|анкета|анкету|заявк|follow\s*up)/i.test(text)) return 'bot_broadcast';
  if (/(анонс.{0,45}(?:эфир|вебинар|мастер[-\s]?класс)|(?:эфир|вебинар|мастер[-\s]?класс).{0,45}анонс|эфир|вебинар|событие)/i.test(text)) return 'live_announcement';
  if (/(цепочк|прогрев|воронк|запуск|серия\s+сообщений|продающ(?:ая|ий|ие))/i.test(text)) return 'sales_sequence';
  return 'auto';
}

const hasAudio = Boolean(audio.file_id);
let selectedTask = '';
if (callbackData.startsWith('format:')) selectedTask = callbackData.slice('format:'.length);
else if (typedFormats[lower]) selectedTask = typedFormats[lower];

let route = 'unsupported';
if (startWords.includes(lower)) route = 'start';
else if (profileWords.includes(lower)) route = 'profile_start';
else if (menuWords.includes(lower)) route = 'help';
else if (formatMenuWords.includes(lower)) route = 'format_menu';
else if (memoryResetWords.includes(lower)) route = 'memory_reset';
else if (memoryOnWords.includes(lower)) route = 'memory_on';
else if (memoryOffWords.includes(lower)) route = 'memory_off';
else if (labels[selectedTask]) route = 'format_button';
else if (hasAudio) route = 'voice';
else if (visibleText.length > 0) route = 'text';

const inferredTask = labels[selectedTask] ? selectedTask : inferTaskFromText(visibleText);

return [{
  json: {
    route,
    source_type: callback ? 'callback' : (hasAudio ? 'voice' : 'text'),
    telegram_id: String(from.id || ''),
    chat_id: String(chat.id || message.chat?.id || ''),
    username: from.username || '',
    first_name: from.first_name || '',
    raw_text: rawText,
    source_text: visibleText,
    callback_data: callbackData,
    callback_query_id: callback?.id || '',
    selected_format_label: labels[selectedTask] || '',
    task_type_hint: inferredTask,
    file_id: audio.file_id || '',
    file_size: Number(audio.file_size || 0),
    duration: Number(audio.duration || 0),
    mime_type: audio.mime_type || (audioKind === 'voice' ? 'audio/ogg' : ''),
    file_name: audio.file_name || '',
    audio_kind: audioKind,
    message_id: message.message_id || callback?.message?.message_id || ''
  }
}];

