    airtable_record_id: record?.id || '',
    daily_requests: Number(fields.daily_requests || 0),
    status: fields.status || 'free',
    memory_mode: String(fields.memory_mode || 'with_memory'),
    request_log: String(fields.request_log || ''),
    last_question: String(fields.last_question || ''),
    last_task_type: String(fields.last_task_type || ''),
    last_raw_text: String(fields.last_raw_text || ''),
    profile_summary: String(fields.profile_summary || ''),
    niche: String(fields.niche || ''),
    audience_summary: String(fields.audience_summary || ''),
    offer_summary: String(fields.offer_summary || ''),
    known_products: String(fields.known_products || ''),
    brand_voice: String(fields.brand_voice || ''),
    limit_exceeded: String(fields.status || 'free') === 'free' && Number(fields.daily_requests || 0) >= 10
  }
}];

const normalized = $('Code - Normalize User').first().json;
const current = $json || {};

let text = String(
  current.text ||
  current.source_text ||
  normalized.source_text ||
  normalized.raw_text ||
  ''
).trim();

const originalText = text;
const lowerOriginal = originalText.toLowerCase().replace(/\s+/g, ' ');
const sourceType = normalized.source_type === 'voice' ? 'voice' : 'text';
const useMemory = String(normalized.memory_mode || 'with_memory') !== 'fresh';

function inferTaskFromText(value) {
  const text = String(value || '').toLowerCase().replace(/\s+/g, ' ');
  if (!text) return 'auto';
  if (/(контент[-\s]?план|контент[-\s]?сетк|план\s+(?:контента|постов|публикац)|сетка\s+контента)/i.test(text)) return 'content_plan';
  if (/(reels?|рилс|рилса|shorts?|сценар(?:ий|ия).{0,70}(?:ролик|reels?|рилс|shorts?)|(?:ролик|reels?|рилс).{0,70}сценар)/i.test(text)) return 'reels_script';
  if (/((?:telegram|телеграм|tg).{0,35}пост|пост.{0,35}(?:telegram|телеграм|tg)|(?:^|\s)пост(?:\s|$))/i.test(text)) return 'telegram_post';
  if (/(рассыл|сообщ\w*.{0,35}(?:бот|дожим|анкеты?|рассыл|письм)|письм[ао]|дожим|дожать|напомин|анкета|анкету|заявк|follow\s*up)/i.test(text)) return 'bot_broadcast';
  if (/(анонс.{0,45}(?:эфир|вебинар|мастер[-\s]?класс)|(?:эфир|вебинар|мастер[-\s]?класс).{0,45}анонс|эфир|вебинар|событие)/i.test(text)) return 'live_announcement';
  if (/(цепочк|прогрев|воронк|запуск|серия\s+сообщений|продающ(?:ая|ий|ие))/i.test(text)) return 'sales_sequence';
  return 'auto';
}

const profile = useMemory ? {
  profile_summary: String(normalized.profile_summary || ''),
  niche: String(normalized.niche || ''),
  audience_summary: String(normalized.audience_summary || ''),
  offer_summary: String(normalized.offer_summary || ''),
  known_products: String(normalized.known_products || ''),
  brand_voice: String(normalized.brand_voice || '')
} : {
  profile_summary: '',
  niche: '',
  audience_summary: '',
  offer_summary: '',
  known_products: '',
  brand_voice: ''
};

const lastQuestion = String(normalized.last_question || '').trim();
const storedTaskType = String(normalized.last_task_type || '').trim();
const isOnboardingAnswer = storedTaskType === 'profile_onboarding' || lastQuestion.startsWith('Профиль эксперта:');
const selectedFormatWaiting = /^(.+?):\s*Нужен бриф:/i.test(lastQuestion);
const incomingTaskType = String(normalized.task_type_hint || '').trim();
const explicitTaskFromText = inferTaskFromText(originalText);
const wordCount = originalText.split(/\s+/).filter(Boolean).length;
const userDelegates = /\b(без разницы|сам придумай|на твое усмотрение|как считаешь|не знаю|любой вариант)\b/i.test(originalText);
const sequenceIntent = /(дожим|дожать|напомин|догрев|follow\s*up|анкета|анкету|заявк|не заполнил|не дошел|не перешел)/i.test(originalText)
  ? 'follow_up'
  : 'regular';

let taskType = 'auto';
if (isOnboardingAnswer) taskType = 'profile_onboarding';
else if (incomingTaskType && incomingTaskType !== 'auto') taskType = incomingTaskType;
else if (explicitTaskFromText !== 'auto') taskType = explicitTaskFromText;
else if (lastQuestion && storedTaskType) taskType = storedTaskType;
if (sequenceIntent === 'follow_up' && taskType === 'auto') taskType = 'bot_broadcast';

const explicitNewTaskOverridesPending = Boolean(
  !isOnboardingAnswer &&
  lastQuestion &&
  explicitTaskFromText !== 'auto' &&
  storedTaskType &&
  explicitTaskFromText !== storedTaskType &&
  wordCount >= 3
);
const hasPendingQuestion = Boolean(lastQuestion) && !explicitNewTaskOverridesPending;
const mustGenerateNow = originalText.length >= 2 && (isOnboardingAnswer || hasPendingQuestion || userDelegates);
const briefStatus = isOnboardingAnswer
  ? (wordCount >= 35 ? 'profile_good' : wordCount >= 12 ? 'profile_partial' : 'profile_thin')
  : (wordCount >= 18 ? 'good' : wordCount >= 7 ? 'partial' : 'thin');
const hasProfileMemory = useMemory && Object.values(profile).some((value) => String(value || '').trim().length > 0);
const rawLastText = hasPendingQuestion && useMemory ? String(normalized.last_raw_text || '').trim() : '';
const lastRawText = rawLastText.includes('Это продолжение после выбранного формата') ? '' : rawLastText.slice(0, 1200);
const requestedMessageCount = Number((originalText.match(/(\d+)\s*(?:сообщ|письм|касани|дожим)/i) || [])[1] || 0);
const styleReference = lowerOriginal.includes('в стиле')
  ? originalText.split(/в стиле/i).slice(1).join('в стиле').trim().slice(0, 2500)
  : '';

if (isOnboardingAnswer) {
  text = [
    'Это заполнение стартового профиля эксперта для памяти бота.',
    'Задача: извлечь факты о человеке, нише, ЦА, болях, продуктах, оффере, стиле, примерах постов и ограничениях.',
    'Если данных достаточно - сохрани профиль. Если совсем мало - задай один большой уточняющий вопрос по недостающим блокам.',
    'Новый ответ пользователя:',
    originalText,
    hasProfileMemory ? '\nСтарый профиль, который можно обновить новыми фактами:\n' + JSON.stringify(profile, null, 2) : ''
  ].filter(Boolean).join('\n');
} else if (mustGenerateNow) {
  text = [
    'Это ответ пользователя на последний вопрос или выбранный формат.',
    'Главное правило: выполнить текущий запрос, не смешивать его с другими прошлыми задачами.',
    'Если деталей не хватает, сделай аккуратные маркетинговые допущения и не задавай второй круг вопросов.',
    lastQuestion ? 'Последний вопрос/выбранный формат: ' + lastQuestion : '',
    lastRawText ? 'Короткий контекст активного брифа: ' + lastRawText : '',
    'Текущий ответ пользователя: ' + originalText
  ].filter(Boolean).join('\n');
}

const isValid = isOnboardingAnswer ? originalText.length >= 2 : text.length >= 2;

const contentDepthHints = {
  content_plan: 'Нужен подробный план с углами, хуками, тезисами и CTA, а не список тем.',
  telegram_post: 'Нужен полноценный готовый пост с сильным началом, логикой, пользой/историей и CTA.',
  reels_script: 'Нужен сценарий с хуками, кадрами, текстом для речи/экрана и CTA.',
  bot_broadcast: 'Нужны полноценные отдельные сообщения рассылки, каждое со своей задачей, а не нарезка одного текста.',
  live_announcement: 'Нужен сильный анонс события с причиной прийти, ценностью и CTA.',
  sales_sequence: 'Нужна связная продающая цепочка с прогревом, возражениями и CTA.',
  auto: 'Нужен готовый маркетинговый материал под текущую задачу без шаблонной воды.'
};

return [{
  json: {
    telegram_id: normalized.telegram_id,
    chat_id: normalized.chat_id,
    airtable_record_id: normalized.airtable_record_id,
    text,
    original_text: originalText,
    source_type: sourceType,
    task_type_hint: taskType,
    explicit_task_from_text: explicitTaskFromText,
    state_task_type: hasPendingQuestion ? storedTaskType : '',
    conversation_memory: '',
    user_profile_context: JSON.stringify(profile, null, 2),
    memory_mode: useMemory ? 'with_memory' : 'fresh',
    has_profile_memory: hasProfileMemory,
    is_onboarding_answer: isOnboardingAnswer,
    last_question: hasPendingQuestion ? lastQuestion : '',
    selected_format_waiting: selectedFormatWaiting && hasPendingQuestion,
    explicit_new_task_overrides_pending: explicitNewTaskOverridesPending,
    is_followup_answer: mustGenerateNow,
    must_generate_now: mustGenerateNow,
    brief_status: briefStatus,
    sequence_intent: sequenceIntent,
    requested_message_count: requestedMessageCount,
    style_reference: styleReference,
    content_depth_hint: contentDepthHints[taskType] || contentDepthHints.auto,
    is_valid: isValid
  }
}];

const message = $json.output?.find?.((item) => item.type === 'message') || $json.output?.[0];
const request = $('Code - Build Marketing Request').first().json;
const raw = String(
  message?.content?.find?.((part) => part.type === 'output_text')?.text ||
  message?.content?.[0]?.text ||
  $json.text ||
  ''
).trim();

function stripFences(value) {
  return value.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
}

function safeJsonParse(value) {
  const cleaned = stripFences(value);
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (_) {}
    }
    return {
      status: 'ready',
      detected_task: request.task_type_hint || 'other',
      result_title: 'Готовый материал',
      summary: '',
      content_blocks: [{ title: 'Материал', body: cleaned }],
      next_steps: [],
      profile_memory_update: {}
    };
  }
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function cleanTitle(value, index) {
  const title = String(value || '').trim();
  const messageMatch = title.match(/^сообщение\s*(\d+)$/i);
  if (messageMatch) return 'Сообщение для рассылки ' + messageMatch[1];
  return title || 'Блок ' + (index + 1);
}

function isBotNextStepBlock(block) {
  const title = String(block.title || '').toLowerCase();
  const body = String(block.body || '').toLowerCase();
  return title.includes('что дальше') ||
    title.includes('что можно сделать дальше') ||
    body.includes('запросите дополнительные идеи') ||
    body.includes('обсудите визуальные элементы');
}

function normalizeBlocks(parsed) {
  if (Array.isArray(parsed.content_blocks)) {
    return parsed.content_blocks.map((block, index) => ({
      title: cleanTitle(block.title, index),
      body: String(block.body || block.text || '')
    })).filter((block) => block.body.trim()).filter((block) => !isBotNextStepBlock(block));
  }
  const blocks = [];
  for (const key of ['telegram_post', 'reels_script', 'bot_broadcast', 'content_plan', 'announcement', 'sales_sequence', 'short_summary']) {
    if (parsed[key]) blocks.push({ title: key, body: String(parsed[key]) });
  }
  return blocks.length ? blocks : [{ title: 'Материал', body: String(parsed.answer || parsed.result || raw) }];
}

function splitText(value, limit) {
  const text = String(value || '');
  if (text.length <= limit) return [text];
  const parts = [];
  let rest = text;
  while (rest.length > limit) {
    let cut = rest.lastIndexOf('\n\n', limit);
    if (cut < limit * 0.45) cut = rest.lastIndexOf('\n', limit);
    if (cut < limit * 0.45) cut = rest.lastIndexOf(' ', limit);
    if (cut < limit * 0.45) cut = limit;
    parts.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) parts.push(rest);
  return parts;
}

function normalizeProfileUpdate(parsed) {
  const update = parsed.profile_memory_update || parsed.user_profile_update || {};
  return {
    profile_summary: String(update.profile_summary || ''),
    niche: String(update.niche || ''),
    audience_summary: String(update.audience_summary || ''),
    offer_summary: String(update.offer_summary || ''),
    known_products: String(update.known_products || ''),
    brand_voice: String(update.brand_voice || '')
  };
}

let parsed = safeJsonParse(raw);
let status = parsed.status === 'need_more_info' ? 'need_more_info' : 'ready';
let task = String(parsed.detected_task || parsed.task_type || request.task_type_hint || 'auto');
const mustGenerateNow = Boolean(request.must_generate_now || request.is_followup_answer || request.selected_format_waiting);

if (request.is_onboarding_answer) {
  task = 'profile_onboarding';
  parsed.detected_task = 'profile_onboarding';
  if (status === 'ready') {
    parsed.result_title = parsed.result_title || 'Профиль собран';
    if (!Array.isArray(parsed.content_blocks) || !parsed.content_blocks.length) {
      parsed.content_blocks = [
        { title: 'Что я запомнил', body: 'Профиль сохранен. Теперь можно присылать задачи текстом или голосом, а я буду учитывать нишу, аудиторию, продукты и стиль.' },
        { title: 'Рабочий режим', body: 'Можно просить: пост, Reels, рассылку в боте, анонс эфира, контент-план или продающую цепочку. Если нужно обновить память, напиши: обновить профиль.' }
      ];
    }
  }
}

if (status === 'need_more_info' && mustGenerateNow && !request.is_onboarding_answer) {
  status = 'ready';
  parsed.status = 'ready';
  parsed.detected_task = task;
  parsed.question = '';
  parsed.result_title = parsed.result_title || 'Рабочий материал по брифу';
  parsed.summary = parsed.summary || 'Собрал по имеющимся вводным. Где деталей не хватало, использовал аккуратные рабочие допущения.';
  if (!Array.isArray(parsed.content_blocks) || !parsed.content_blocks.length) {
    parsed.content_blocks = [{ title: 'Материал', body: String(raw || '').trim() || 'Не получилось извлечь текст. Попробуй прислать бриф еще раз одним сообщением.' }];
  }
}

const profileMemoryUpdate = normalizeProfileUpdate(parsed);
const messages = [];

if (status === 'need_more_info') {
  const question = String(parsed.question || (task === 'profile_onboarding'
    ? 'Расскажи одним сообщением: кто ты, ниша, ЦА, что продаешь, боли аудитории, стиль и примеры постов.'
    : 'Пришли одним сообщением: что нужно написать, что продвигаем, для кого, цель, дедлайн/ссылка и тон. Если детали нет - напиши "сам придумай".')).trim();
  if (task === 'profile_onboarding') {
    messages.push([
      '<b>Нужно чуть больше для профиля</b>',
      '',
      escapeHtml(question),
      '',
      'Можно ответить голосовым. Я соберу выжимку и запомню.'
    ].join('\n'));
  } else {
    messages.push([
      '<b>Чтобы написать не воду, нужен один бриф</b>',
      '',
      escapeHtml(question),
      '',
      'Можно ответить коротко или голосом. Если профиль заполнен, нишу и аудиторию я беру из памяти.'
    ].join('\n'));
  }
} else {
  const blocks = normalizeBlocks(parsed);
  if (!blocks.length) {
    const title = String(parsed.result_title || 'Готовый маркетинговый материал');
    messages.push('<b>' + escapeHtml(title) + '</b>');
  }

  for (const block of blocks) {
    const chunks = splitText(block.body, 3000);
    chunks.forEach((chunk, index) => {
      const suffix = chunks.length > 1 ? ' (' + (index + 1) + '/' + chunks.length + ')' : '';
      messages.push('<b>' + escapeHtml(block.title + suffix) + '</b>\n\n' + escapeHtml(chunk));
    });
  }
}

return [{
  json: {
    raw_model_output: raw,
    parsed,
    profile_memory_update: profileMemoryUpdate,
    response_status: status,
    detected_task: task,
    result_for_log: JSON.stringify(parsed).slice(0, 6000),
    messages
  }
}];

