const input = $('Code - Normalize User').first().json;

const labels = {
  content_plan: 'Контент-план',
  telegram_post: 'Telegram-пост',
  reels_script: 'Reels-сценарий',
  bot_broadcast: 'Рассылка в боте',
  live_announcement: 'Анонс эфира',
  sales_sequence: 'Продающая цепочка',
};

const task = input.task_type_hint && input.task_type_hint !== 'auto' ? input.task_type_hint : 'telegram_post';
const title = labels[task] || 'Маркетинговый материал';
const hasProfile = Boolean(
  String(input.profile_summary || '').trim() ||
  String(input.niche || '').trim() ||
  String(input.audience_summary || '').trim() ||
  String(input.offer_summary || '').trim()
);

const profileLine = hasProfile
  ? 'Нишу, ЦА, оффер и стиль беру из профиля. Пришли только вводные по этой задаче.'
  : 'Профиль пока пустой. Лучше сначала заполнить его через /start, но можно продолжить и сейчас.';

const briefs = {
  content_plan: {
    ask: 'на сколько дней нужен план, что продвигаем сейчас, главная цель, куда вести людей, какие даты/эфиры/акции учесть.',
    example: 'пример: план на 7 дней перед эфиром, цель - регистрации в бота, продвигаем клуб, CTA - перейти по ссылке, тон дерзкий и экспертный.',
  },
  telegram_post: {
    ask: 'тема поста, цель поста, что читатель должен почувствовать/понять, куда вести, есть ли личная история, кейс или важные факты.',
    example: 'пример: пост в Telegram про страх начинать с ботами, цель - записать на эфир, CTA - нажать кнопку в боте, стиль живой и уверенный.',
  },
  reels_script: {
    ask: 'тема ролика, цель, кому говорим, какой главный инсайт/обещание, что показать в кадре, куда вести после ролика.',
    example: 'пример: Reels про простого бота за час для нутрициологов, цель - переход в бота, нужен хук, текст в кадре, голос и CTA.',
  },
  bot_broadcast: {
    ask: 'сколько сообщений нужно, повод/что продвигаем, для кого, какая боль или желание, дедлайн/дата/ссылка, какой следующий шаг.',
    example: 'пример: 3 сообщения дожима на анкету диагностики, аудитория - женщины после медитации, цель - заполнить анкету, стиль мягкий как в примере ниже.',
  },
  live_announcement: {
    ask: 'тема эфира, для кого он, какой результат человек получит, дата/время, что продаем или куда ведем после эфира, главный CTA.',
    example: 'пример: анонс эфира завтра 20:00 про бота проверки подписки, для экспертов, цель - регистрация в клуб, CTA - перейти в бота.',
  },
  sales_sequence: {
    ask: 'что продаем, длительность цепочки, сегмент аудитории, текущая стадия прогрева, ключевые возражения, дедлайн и CTA.',
    example: 'пример: цепочка на 5 касаний перед продажей клуба, ЦА уже была на эфире, возражение - нет времени, цель - оплатить подписку.',
  },
};

const brief = briefs[task] || briefs.telegram_post;
const text = [
  '<b>' + title + '</b>',
  '',
  profileLine,
  '',
  'Пришли одним сообщением: ' + brief.ask,
  '',
  '<i>' + brief.example + '</i>',
  '',
  'Если какой-то детали нет, так и напиши: «сам придумай». Голосовые тоже подходят.',
].join('\n');

return [{
  json: {
    ...input,
    selected_task_type: task,
    selected_format_label: title,
    last_question: title + ': ' + brief.ask,
    format_brief_text: text,
  },
}];

