parameters.jsCode:
const user = $('Code - Normalize User').first().json;

function filled(value, min = 20) {
  return String(value || '').trim().length >= min;
}

const coreCount = [
  filled(user.niche, 8),
  filled(user.audience_summary, 30),
  filled(user.offer_summary, 25),
  filled(user.brand_voice, 12),
].filter(Boolean).length;
const hasProfile = filled(user.profile_summary, 80) || coreCount >= 3;
const forceUpdate = user.route === 'profile_start';
const onboardingNeeded = forceUpdate || !hasProfile;

const onboardingText = [
  '<b>Давай сначала соберу твой профиль</b>',
  '',
  'Чтобы потом писать за тебя нормально, мне нужно понять нишу, аудиторию, продукты и стиль.',
  '',
  'Ответь одним сообщением или голосовым:',
  '',
  '1. кто ты и чем занимаешься',
  '2. какая ниша и для кого работаешь',
  '3. что продаешь: клуб, курс, практики, консультации, эфиры, бот',
  '4. какая боль/желание у аудитории',
  '5. чем ты отличаешься и какие есть смыслы/позиция',
  '6. примеры постов, фраз, тональности, которые нравятся',
  '7. что точно нельзя писать или обещать',
  '',
  'Можно надиктовать как есть. Я сам соберу выжимку и запомню.'
].join('\n');

const menuText = [
  '<b>Профиль уже есть, можно работать</b>',
  '',
  'Я помню нишу, аудиторию, оффер и стиль. Теперь можно просто писать задачу: пост, Reels, рассылка, анонс, контент-план или цепочка.',
  '',
  'Если хочешь обновить память, напиши: <b>обновить профиль</b>.'
].join('\n');

return [{
  json: {
    chat_id: user.chat_id,
    airtable_record_id: user.airtable_record_id,
    onboarding_needed: onboardingNeeded,
    telegram_text: onboardingNeeded ? onboardingText : menuText,
    last_task_type: 'profile_onboarding',
    last_question: 'Профиль эксперта: Нужна анкета: кто вы, ниша, ЦА, боли/желания, продукты, оффер, стиль, примеры постов, ограничения.',
    last_raw_text: 'Старт онбординга профиля'
  }
}];

